  /* ================= Standard form ================= */
  function mant(D,k){var s=String(D);if(!k)return s;while(s.length<=k)s="0"+s;return s.slice(0,s.length-k)+"."+s.slice(s.length-k);}
  function sfS(D,k,e){return mant(D,k)+" × 10"+sup(e);}
