    var D=num(j.D),S=num(j.s),T=hrsDec(j.t),en,ans,pool,why;
    if(kind==="speed"){en="A train goes "+km(j.D)+" in "+hm(j.t)+". Which calculation gives its average speed in km/h?";ans=D+" ÷ "+T;
      pool=[D+" × "+T,T+" ÷ "+D,D+" ÷ "+j.t];if(j.t%60)pool.push(D+" ÷ "+Math.floor(j.t/60)+"."+(j.t%60));why="Speed = distance ÷ time, with the time in HOURS ("+hm(j.t)+" = "+T+" hours).";}
