    if(Math.random()<.5)return Q("Change "+kmh(k)+" into metres per second.","",v,[k*3.6,k/60,k*1000/60,k/3.6*10,v+2,v*2],ms,
      kmh(k)+" = "+num(k*1000)+" m in 3,600 s: "+num(k*1000)+" ÷ 3,600 = "+ms(v)+". (Quick way: ÷ 3.6.)","",{t:"tomps"});
    return Q("Change "+ms(v)+" into kilometres per hour.","",k,[v/3.6,v*60,v*3600,k+10,v*36,k/2],kmh,
      ms(v)+" × 3,600 s = "+num(v*3600)+" m an hour = "+kmh(k)+". (Quick way: × 3.6.)","",{t:"tokmh"});
